import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { ENHANCE_SYSTEM_PROMPT } from "../dist/core/system-prompt.js";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const pkg = JSON.parse(fs.readFileSync(path.join(HERE, "..", "package.json"), "utf8"));

/* 1) Canonical enhancement rules for the desktop layer (single source:
 * src/core/system-prompt.ts via the compiled dist output). */
const OUT = path.join(HERE, "..", "desktop", "system-prompt.generated.js");
const body =
  "/* GENERATED by scripts/embed-system-prompt.mjs — do not edit by hand. */\n" +
  "window.__PE_SYSTEM_PROMPT = " + JSON.stringify(ENHANCE_SYSTEM_PROMPT) + ";\n";
fs.writeFileSync(OUT, body, "utf8");
console.log(`[prompt-enhancer] wrote ${OUT} (${ENHANCE_SYSTEM_PROMPT.length} chars)`);

/* 2) Stamp the overlay's VERSION (shared script — see stamp-overlay-version.mjs).
 * Run here so `npm run build` remains the single documented build entry. */
await import("./stamp-overlay-version.mjs");
